// STUTI_NITYA_Q/_AUTO/_SPEED: ad-hoc cross-screen globals Home and Reader
// poked directly (see src/stuti-nitya-queue.ts, hand-written, not
// regenerated by transform.mjs). Rewrites the handful of call sites in
// both screens to use that store instead.
import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(HERE, "../../src");
const rd = (f) => readFileSync(join(OUT, f), "utf8");
const wr = (f, t) => writeFileSync(join(OUT, f), t);

wr(
  "stuti-nitya-queue.ts",
  `/* ============================================================
   STUTI — the "what's queued next" handoff between Home and Reader
   Home's daily list hands the Reader a whole queue (not just the one
   hymn tapped) so "Begin" can auto-advance through the rest of the
   list. Used to be window.STUTI_NITYA_Q/_AUTO/_SPEED, three loose
   globals two screens poked directly; same shape, module-scoped.
   ============================================================ */
export type NityaQueue = { ids: string[]; idx: number; from?: string } | null;

let queue: NityaQueue = null;
let autoAdvance = false;
let speed = 1;

export const nityaQueue = {
  get: () => queue,
  set: (q: NityaQueue) => { queue = q; },
  getAuto: () => autoAdvance,
  setAuto: (v: boolean) => { autoAdvance = v; },
  getSpeed: () => speed,
  setSpeed: (v: number) => { speed = v; },
};
`
);

function patch(file, anchorImportBefore, replacements) {
  let text = rd(file);
  if (!text.includes('from "./stuti-nitya-queue"')) {
    text = text.replace(anchorImportBefore, `import { nityaQueue } from "./stuti-nitya-queue";\n${anchorImportBefore}`);
  }
  for (const [from, to] of replacements) {
    if (!text.includes(from)) throw new Error(`${file}: pattern not found:\n${from}`);
    text = text.replace(from, to);
  }
  wr(file, text);
}

patch("stuti-home.tsx", 'import { STUTI_MUHURTA } from "./stuti-muhurta";', [
  [
    `window.STUTI_NITYA_Q = list.length > 1 ? { ids: list.map(x => x.id), idx: Math.max(0, idx), from } : null;`,
    `nityaQueue.set(list.length > 1 ? { ids: list.map(x => x.id), idx: Math.max(0, idx), from } : null);`,
  ],
  [
    `window.STUTI_NITYA_Q = queue.length > 1 ? { ids: queue.map(x => x.id), idx: 0, from } : null;`,
    `nityaQueue.set(queue.length > 1 ? { ids: queue.map(x => x.id), idx: 0, from } : null);`,
  ],
]);

patch("stuti-reader.tsx", 'import { STUTI_TRANSLIT } from "./stuti-translit";', [
  [
    `return (window.STUTI_NITYA_AUTO && window.STUTI_NITYA_SPEED) || (Number.isFinite(saved) ? saved : 1);`,
    `return (nityaQueue.getAuto() && nityaQueue.getSpeed()) || (Number.isFinite(saved) ? saved : 1);`,
  ],
  [`const nq = window.STUTI_NITYA_Q;`, `const nq = nityaQueue.get();`],
  [
    `if (window.STUTI_NITYA_AUTO) { window.STUTI_NITYA_AUTO = false; setActive(0); setPlaying(true); }`,
    `if (nityaQueue.getAuto()) { nityaQueue.setAuto(false); setActive(0); setPlaying(true); }`,
  ],
  [
    `window.STUTI_NITYA_Q = { ids: nq.ids, idx: nq.idx + 1, from: nq.from };\n      window.STUTI_NITYA_AUTO = true;\n      window.STUTI_NITYA_SPEED = speed;`,
    `nityaQueue.set({ ids: nq.ids, idx: nq.idx + 1, from: nq.from });\n      nityaQueue.setAuto(true);\n      nityaQueue.setSpeed(speed);`,
  ],
  [
    `setNextUp(null); window.STUTI_NITYA_Q = null; }} aria-label={STUTI_L.a("aClose")}>×</button>`,
    `setNextUp(null); nityaQueue.set(null); }} aria-label={STUTI_L.a("aClose")}>×</button>`,
  ],
]);

console.log("nitya-queue patched");
